const s = wb.getWorksheet('OUPUT');
for (let r = 2; r <= 6; r++) {
  s.getRange(`A${r}`).setValue(`=INPUT!A${r}`);
  s.getRange(`B${r}`).setValue(`=INPUT!C${r}`);
  s.getRange(`C${r}`).setValue(`=INPUT!E${r}`);
  s.getRange(`D${r}`).setValue(`=IFERROR(INDEX({"USA","FRA","KOR","GR","IT"},MATCH(INPUT!F${r},{"UNATIDE STATES AMERICAN","FRANCE","KOREA","GERMANY","ITALY"},0)),INPUT!F${r})`);
}
log(JSON.stringify(s.getRange('A1:D6').getValues()));
log(JSON.stringify(s.getRange('A1:D6').getTexts?.() ?? null));
log(s.getRange('D6').getCell());
log(JSON.stringify(wb.getRange('INPUT!A2:F6').getValues()));

